#include <iostream>

struct ConfigError {
    virtual ~ConfigError() = default;
    virtual const char* label() const { return "config"; }
};

struct MissingKey : ConfigError {
    const char* label() const override { return "missing-key"; }
};

void load(int stage) {
    if (stage == 0) {
        throw MissingKey{};
    }
    throw ConfigError{};
}

int main() {
    for (int stage : {0, 1}) {
        try {
            try {
                load(stage);
            } catch (ConfigError error) {
                std::cout << "inner " << error.label() << ' ';
                if (stage == 0) {
                    throw;
                }
            }
        } catch (const ConfigError& error) {
            std::cout << "outer " << error.label() << ' ';
        }
    }
    std::cout << '\n';
}

