#include <iostream>
#include <stdexcept>
#include <vector>

struct Cart {
    std::vector<int> lines;
    int units = 0;  // invariant: sum of lines
};

void add_in_place(Cart& cart, int quantity) {
    cart.lines.push_back(quantity);
    if (cart.units + quantity > 10) {
        throw std::runtime_error{"over limit"};
    }
    cart.units += quantity;
}

void add_prepared(Cart& cart, int quantity) {
    Cart next = cart;
    next.lines.push_back(quantity);
    next.units += quantity;
    if (next.units > 10) {
        throw std::runtime_error{"over limit"};
    }
    cart.lines.swap(next.lines);
    cart.units = next.units;
}

int main() {
    Cart a;
    Cart b;
    for (int quantity : {6, 7}) {
        try { add_in_place(a, quantity); } catch (const std::exception&) {}
        try { add_prepared(b, quantity); } catch (const std::exception&) {}
    }
    std::cout << a.lines.size() << ' ' << a.units << " | "
              << b.lines.size() << ' ' << b.units << '\n';
}

