#include <iostream>
#include <stdexcept>

struct Reservoir {
    int capacity_ml;
    int stored_ml;
};

void top_up(Reservoir& tank, int pumps, int ml_per_pump) {
    const int added = pumps * ml_per_pump;
    const int next = tank.stored_ml + added;

    if (next > tank.capacity_ml) {
        throw std::runtime_error{"would overflow the tank"};
    }

    tank.stored_ml = next;
}

int main() {
    Reservoir tank{2000000000, 0};

    try {
        top_up(tank, 100000, 50000);
        std::cout << "accepted\n";
    } catch (const std::runtime_error&) {
        std::cout << "rejected\n";
    }

    std::cout << tank.stored_ml << '\n';
}

