#include <cstddef>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

class EventLog {
public:
    explicit EventLog(std::size_t byte_cap) : byte_cap_(byte_cap) {}

    // Strong guarantee: if this throws, entries() and bytes() are exactly what
    // they were on entry, and they still agree with each other.
    void record(std::string_view text) {
        const std::size_t next_bytes = bytes_ + text.size();

        // Validate before touching anything.
        if (next_bytes > byte_cap_) {
            throw std::length_error{"event log cap exceeded"};
        }

        // The only remaining step that can throw is this one, and push_back is
        // itself strong: if the allocation fails, entries_ is unchanged.
        entries_.push_back(std::string{text});

        // Commit: a non-throwing assignment, so the two fields can never be
        // observed out of step.
        bytes_ = next_bytes;
    }

    [[nodiscard]] std::size_t entries() const noexcept { return entries_.size(); }
    [[nodiscard]] std::size_t bytes() const noexcept { return bytes_; }

private:
    std::vector<std::string> entries_;
    std::size_t bytes_ = 0;
    std::size_t byte_cap_;
};

#include <cstddef>

class TextureCache {
public:
    int acquire_slot();                                        // -1 when full
    void release_slot(int slot) noexcept;
    void upload(int slot, const unsigned char* pixels, std::size_t bytes);
    void publish(int slot) noexcept;
};

class SlotGuard {
public:
    SlotGuard(TextureCache& cache, int slot) noexcept
        : cache_(&cache), slot_(slot) {}

    ~SlotGuard() noexcept {
        if (armed_) {
            cache_->release_slot(slot_);
        }
    }

    void dismiss() noexcept { armed_ = false; }

private:
    TextureCache* cache_;
    int slot_;
    bool armed_ = true;
};

bool install_texture(TextureCache& cache, const unsigned char* pixels,
                     std::size_t bytes) {
    const int slot = cache.acquire_slot();
    if (slot < 0) {
        return false;  // nothing acquired yet, so nothing to guard
    }

    // Declared after the slot exists and after cache, which outlives it.
    SlotGuard guard{cache, slot};

    cache.upload(slot, pixels, bytes);  // may throw: unwinding releases the slot

    if (bytes == 0) {
        return false;  // early return: guard still armed, slot goes back
    }

    cache.publish(slot);
    guard.dismiss();  // committed; the slot now belongs to the cache
    return true;
}

