#include <cstdint>
#include <expected>
#include <string_view>

struct Color {
    std::uint8_t red;
    std::uint8_t green;
    std::uint8_t blue;
};

enum class ColorError {
    empty,
    missing_hash,
    wrong_length,
    bad_digit
};

[[nodiscard]] std::expected<Color, ColorError>
parse_color(std::string_view text) {
    if (text.empty()) {
        return std::unexpected(ColorError::empty);
    }
    if (text.front() != '#') {
        return std::unexpected(ColorError::missing_hash);
    }
    if (text.size() != 7) {
        return std::unexpected(ColorError::wrong_length);
    }

    std::uint32_t value = 0;
    for (char character : text.substr(1)) {
        std::uint32_t digit = 0;
        if (character >= '0' && character <= '9') {
            digit = static_cast<std::uint32_t>(character - '0');
        } else if (character >= 'a' && character <= 'f') {
            digit = static_cast<std::uint32_t>(character - 'a') + 10;
        } else if (character >= 'A' && character <= 'F') {
            digit = static_cast<std::uint32_t>(character - 'A') + 10;
        } else {
            return std::unexpected(ColorError::bad_digit);
        }
        value = value * 16 + digit;
    }

    return Color{static_cast<std::uint8_t>(value >> 16),
                 static_cast<std::uint8_t>((value >> 8) & 0xFF),
                 static_cast<std::uint8_t>(value & 0xFF)};
}

#include <exception>
#include <stdexcept>
#include <string>

class JobCancelled : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

class JobFailed : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

int active_jobs = 0;

class ActiveJob {
public:
    ActiveJob() noexcept { ++active_jobs; }
    ~ActiveJob() noexcept { --active_jobs; }
    ActiveJob(const ActiveJob&) = delete;
    ActiveJob& operator=(const ActiveJob&) = delete;
};

void run_stage(const std::string& stage);

void run_job(const std::string& stage) {
    // Decremented on every exit, including an unwind: no handler in this
    // function needs to know about the counter at all.
    ActiveJob active;

    try {
        run_stage(stage);
    } catch (const JobCancelled&) {
        // Derived before base: cancellation is not a failure and must reach
        // the scheduler with its own type intact.
        throw;
    } catch (const std::exception& error) {
        // Translate into this layer's vocabulary, adding the stage name.
        throw JobFailed{stage + ": " + error.what()};
    } catch (...) {
        // Unknown type: rethrow unchanged. An empty handler here would turn a
        // known failure into unknown state.
        throw;
    }
}

