#include <cstddef>
#include <expected>
#include <vector>

enum class RingError {
    zero_capacity,
    not_power_of_two,
    too_large
};

class Ring {
public:
    // Infallible: make_ring has already established the precondition that
    // capacity is a non-zero power of two within the allowed range.
    explicit Ring(std::size_t capacity)
        : cells_(capacity), mask_(capacity - 1) {}

    [[nodiscard]] std::size_t capacity() const noexcept { return cells_.size(); }
    [[nodiscard]] std::size_t wrap(std::size_t index) const noexcept {
        return index & mask_;
    }

private:
    std::vector<int> cells_;
    std::size_t mask_;
};

[[nodiscard]] std::expected<Ring, RingError> make_ring(std::size_t capacity) {
    if (capacity == 0) {
        return std::unexpected(RingError::zero_capacity);
    }
    if ((capacity & (capacity - 1)) != 0) {
        return std::unexpected(RingError::not_power_of_two);
    }
    if (capacity > (std::size_t{1} << 20)) {
        return std::unexpected(RingError::too_large);
    }
    return Ring{capacity};
}

#include <cassert>
#include <cstdio>
#include <cstdlib>

inline constexpr unsigned kSlotMagic = 0x46524D31u;

struct FrameSlot {
    unsigned magic;
    unsigned char* plane[3];
    int stride;
};

bool reset_decoder_pool();

void decode_plane(FrameSlot& slot, int plane) {
    // Internal invariant. The only caller is our own loop over a three-plane
    // image, so a violation is a bug in this file, and NDEBUG deleting the
    // check costs production nothing. Nothing with a side effect may go here:
    // `assert(reset_decoder_pool());` would stop resetting anything in a
    // release build.
    assert(plane >= 0 && plane < 3);

    // Trust boundary. The slot comes from the driver, so this check has to
    // survive into the shipped build and therefore cannot be an assert.
    // Decoding into a corrupted slot descriptor is worse than stopping.
    if (slot.magic != kSlotMagic) {
        std::fputs("frame slot magic corrupted\n", stderr);
        std::fflush(stderr);  // abort does not flush buffered output
        std::abort();
    }

    std::printf("decoding plane %d, stride %d\n", plane, slot.stride);
}
